{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello राहुल आपको pad printing ink की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "Yes yes."
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "कितने kg चाहिए होंगे आपको?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "एक किलो चाहिए।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "चलिए अब substrate के बारे में बताइए आपको किस तरह का चाहिए ABS, steel, plastic या glass या कुछ और?"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "हाँ लकड़ी में printing करना है।"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "wood में।"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "जैसे कि चामुची हो गया।"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "ऊग गया।"
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "वैसे ही।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "समझ गई आपको wood जैसे चम्मच या लकड़ी की चीजों पर printing करनी है।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "अब ink system में क्या prefer करेंगे two component या single component या कुछ और चाहिए?"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "तुमको component क्या एक kg में मिल जाएगा?"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "जी, 2 component option available रहेगा।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "seller आपको 1 kg में दे सकते हैं।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "बाकी जानकारी और price seller से discuss कर सकते हैं।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price..."
    }
  ]
}
